PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE words (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      latin TEXT NOT NULL UNIQUE,
      amharic TEXT NOT NULL
    , pronunciation_audio BLOB, pronunciation_mime TEXT, pronunciation_source TEXT, translation TEXT);
CREATE TABLE characters (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      fidel TEXT NOT NULL,
      latin TEXT NOT NULL,
      family TEXT NOT NULL
    );
CREATE TABLE drawing_samples (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      expected TEXT NOT NULL,
      features TEXT NOT NULL,
      label TEXT NOT NULL,
      image TEXT,
      source TEXT,
      created_at TEXT DEFAULT (datetime('now'))
    );
COMMIT;
